public static int maxRegions(int N) {
  // Step 1: Calculate the maximum number of regions for a grid of size (N x N)
  int maxRegions = (int)Math.pow(2, N);

  // Step 2: Calculate the number of regions for a grid of size (N x N - 1)
  int regions = (int)Math.pow(2, N - 1);

  // Step 3: Iterate until the number of regions for the current grid is equal to the maximum number of regions
  // Step 3.1: Decrease the size of the grid by one row and one column
  while (regions != maxRegions) {
    regions = (int)Math.pow(2, N - 1);
    N -= 1;
  }

  // Step 4: Return the maximum number of regions
  return maxRegions;
}

