public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
      // Base case: If the starting and ending n-tersections are the same, return "can be travelled"
      if (Arrays.equals(start, end)) {
          return "can be travelled";
      }

      // Mark all n-tersections as unvisited
      boolean[] visited = new boolean[n];
      for (int i = 0; i < n; i++) {
          visited[i] = false;
      }

      // Create a queue to maintain the order of visited n-tersections
      Queue<Integer> queue = new LinkedList<>();

      // Add the starting n-tersection to the queue
      queue.offer(start[0]);

      // Set the starting n-tersection as visited
      visited[start[0]] = true;

      // Loop until all n-tersections are visited
      while (!queue.isEmpty()) {
          // Get the current n-tersection from the queue
          int current = queue.poll();

          // If the current n-tersection is the ending n-tersection, return "can be travelled"
          if (Arrays.equals(current, end)) {
              return "can be travelled";
          }

          // Add the neighbors of the current n-tersection to the queue
          for (int[] path : paths) {
              if (!visited[path[0]]) {
                  visited[path[0]] = true;
                  queue.offer(path[0]);
              }
          }
      }

      // If no path is found, return "cannot be travelled"
      return "cannot be travelled";
  }

