    // Breadth-first search
    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }
        for (int[] path : paths) {
            int[] next = new int[] {current[0] + path[0], current[1] + path[1]};
            if (next[0] < 0 || next[1] < 0 || next[0] >= n || next[1] >= n) {
                continue;
            }
            if (!visited[next[0] * n + next[1]]) {
                visited[next[0] * n + next[1]] = true;
                queue.offer(next);
            }
        }
    }

    return "cannot be travelled";
}

