        .setInstant(java.time.Instant.ofEpochMilli(0))
        .setCalendarType("gregory")
        .setDayOfMonth(day)
        .setMonth(month - 1)
        .setYear(year)
        .build().get(java.util.Calendar.DAY_OF_WEEK)) {
    case java.util.Calendar.SUNDAY:
