    // Handle edge cases
    if (nums == null || nums.length == 0) {
        return -1;
    }

    // Find the pivot index
    int pivot = findPivot(nums);

    // Search the left and right subarrays
    int left = searchSubarray(nums, 0, pivot, target);
    int right = searchSubarray(nums, pivot + 1, nums.length - 1, target);

    // Return the first match
    if (left != -1) {
        return left;
    } else if (right != -1) {
        return right;
    } else {
        return -1;
    }
}

public int search(int[] nums, int target) {
    int left = 0;
    int right = nums.length - 1;

    while (left <= right) {
        int mid = (left + right) / 2;
        if (nums[mid] == target) {
            return mid;
        }

        if (nums[left] <= nums[mid]) {
            // Left half is sorted
            if (target < nums[mid] && target >= nums[left]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            // Right half is sorted
            if (target > nums[mid] && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }

    return -1;
}

