}

public int search(int[] nums, int target) {
    // Find the pivot index using binary search
    int left = 0;
    int right = nums.length - 1;
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] > nums[right]) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    // Search for the target value in the pivot section
    int pivot = left;
    int low = pivot;
    int high = nums.length - 1;
    while (low <= high) {
        int middle = (low + high) / 2;
        if (nums[middle] == target) {
            return middle;
        } else if (nums[middle] < target) {
            low = middle + 1;
        } else {
            high = middle - 1;
        }
    }
    // Search for the target value in the non-pivot section
    low = 0;
    high = pivot - 1;
    while (low <= high) {
        int middle = (low + high) / 2;
        if (nums[middle] == target) {
            return middle;
        } else if (nums[middle] < target) {
            low = middle + 1;
        } else {
            high = middle - 1;
        }
    }
    return -1;
}

