}

public double trimMean(int[] arr) {
      // Sort the array in ascending order
      Arrays.sort(arr);

      // Calculate the index of the 5th percentile and the index of the 95th percentile
      int index5thPercentile = (int) (arr.length * 0.05);
      int index95thPercentile = (int) (arr.length * 0.95);

      // Remove the smallest 5% and largest 5% of elements
      int[] trimmedArr = Arrays.copyOfRange(arr, index5thPercentile, index95thPercentile);

