public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Compute the number of elements to remove from the extremes
    int numElementsToRemove = (int) Math.floor(arr.length * 0.05);

    // Remove the smallest and largest elements
    int[] trimmedArr = Arrays.copyOfRange(arr, numElementsToRemove, arr.length - numElementsToRemove);

    // Find the mean of the remaining elements
    double mean = trimmedArr.stream().mapToDouble(x -> x).average().orElse(0);

    // Return the mean with an error within 10^-5
    return Math.round(mean * Math.pow(10, 5)) / Math.pow(10, 5);
}

