function canArrange(int[] arr, int k) {

    /**
     * Check if it is possible to divide the array into n/2 pairs such that the sum of each pair is divisible by k.
     * @param arr the input integer array
     * @param k the divisor
     * @return true if it is possible, false otherwise
     */

    // if the length of the array is not divisible by 2, return false
    if (arr.length % 2 != 0) {
        return false;
    }

    // create a set to store the pairs
    Set<Integer> pairs = new HashSet<>();

    // loop through the array
    for (int i = 0; i < arr.length - 1; i += 2) {

        // get the sum of the current pair
        int sum = arr[i] + arr[i + 1];

        // if the sum is divisible by k, add the pair to the set
        if (sum % k == 0) {
            pairs.add(sum);
        }
    }

    // if the set is not empty, return true
    if (!pairs.isEmpty()) {
        return true;
    }

    // otherwise, return false
    return false;
}

