}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
  /*
   * Corner cases:
   * (1) If there are no apples, return 0.
   * (2) If there is only one apple, return the time required to collect it.
   */
  if (hasApple.length == 1) {
    return hasApple[0] ? 1 : 0;
  } else if (hasApple.length == 0) {
    return 0;
  }

  /*
   * Compute the time required to collect apples at each vertex.
   * The time required to collect an apple is 1.
   */
  int[] times = new int[n];
  for (int i = 0; i < n; i++) {
    times[i] = hasApple[i] ? 1 : 0;
  }

  /*
   * Compute the time required to collect apples at each edge.
   * The time required to collect an apple is 1.
   */
  for (int[] edge : edges) {
    times[edge[0]] += times[edge[1]];
    times[edge[1]] += times[edge[0]];
  }

  /*
   * Compute the time required to collect all apples by taking the maximum time at each vertex.
   */
  int[] maxTimes = new int[n];
  for (int i = 0; i < n; i++) {
    maxTimes[i] = times[i];
  }
  for (int[] edge : edges) {
    maxTimes[edge[0]] = Math.max(maxTimes[edge[0]], maxTimes[edge[1]]);
    maxTimes[edge[1]] = Math.max(maxTimes[edge[0]], maxTimes[edge[1]]);
  }

  /*
   * Return the maximum time required to collect all apples.
   */
  return Arrays.stream(maxTimes).max().getAsInt();
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] dist = new int[n];
    for (int i = 0; i < n; i++) {
        dist[i] = -1;
    }
    dist[0] = 0;

    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);
    while (!queue.isEmpty()) {
        int node = queue.remove();
        if (dist[node] < 0) {
            continue;
        }
        for (int i = 0; i < edges.length; i++) {
            if (edges[i][0] == node && dist[edges[i][1]] < 0) {
                dist[edges[i][1]] = dist[node] + 1;
                if (hasApple[edges[i][1]]) {
                    return dist[edges[i][1]] + 1;
                }
                queue.add(edges[i][1]);
            }
        }
    }

    return 0;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with n nodes and edges
    Graph graph = new Graph(n, edges);

    // Initialize a array to store the minimum time required to collect all the apples and return to node 0
    int[] minTime = new int[n];
    Arrays.fill(minTime, Integer.MAX_VALUE);

    // Set the minimum time for node 0 to 0
    minTime[0] = 0;

    // Loop through each node
    for (int i = 0; i < n; i++) {
        // If the node has an apple, then the minimum time to collect all the apples and return to node 0 is 0
        if (hasApple[i]) {
            minTime[i] = 0;
        }

        // Loop through each neighbor of the current node
        for (int j = 0; j < graph.nEdges[i]; j++) {
            // Get the neighbor node and the weight of the edge between the current node and the neighbor node
            int neighbor = graph.edges[i][j];
            int weight = graph.weights[i][j];

            // If the minimum time to collect all the apples and return to node 0 for the neighbor node is less than or equal to the current minimum time plus the weight of the edge between the current node and the neighbor node, then update the minimum time
            if (minTime[neighbor] > minTime[i] + weight) {
                minTime[neighbor] = minTime[i] + weight;
            }
        }
    }

    // Return the minimum time to collect all the apples and return to node 0 for node 0
    return minTime[0];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Create a graph data structure with the given nodes and edges
    Graph graph = new Graph(n, edges);

    // Initialize an array to store the minimum time required to collect apples at each node
    int[] minTime = new int[n];
    Arrays.fill(minTime, Integer.MAX_VALUE);

    // Initialize a queue to store the nodes to visit
    Queue<Integer> queue = new LinkedList<>();

    // Initialize the start node and its minimum time
    int startNode = 0;
    minTime[startNode] = 0;
    queue.add(startNode);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node and its minimum time
        int currentNode = queue.remove();
        int currentTime = minTime[currentNode];

        // Check if the current node has an apple
        if (hasApple[currentNode]) {
            // If the current node has an apple, add its time to the minimum time
            minTime[currentNode] = currentTime + 1;
        }

        // Iterate over the neighbors of the current node
        for (int neighbor : graph.neighbors(currentNode)) {
            // If the neighbor has not been visited before, mark it as visited and add it to the queue
            if (minTime[neighbor] == Integer.MAX_VALUE) {
                minTime[neighbor] = currentTime + 1;
                queue.add(neighbor);
            }
        }
    }

    // Return the minimum time required to collect all the apples
    return minTime[startNode];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Step 1: Create a map from each node to its neighbors
    Map<Integer, List<Integer>> graph = new HashMap<>();
    for (int i = 0; i < edges.length; i++) {
        int source = edges[i][0];
        int destination = edges[i][1];
        if (graph.containsKey(source)) {
            graph.get(source).add(destination);
        } else {
            List<Integer> neighbors = new ArrayList<>();
            neighbors.add(destination);
            graph.put(source, neighbors);
        }

        if (hasApple[i]) {
            return 0;
        }
    }

    // Step 2: DFS to traverse the tree and compute the minimum time required to reach each node
    // with an apple
    Queue<Integer> queue = new LinkedList<>();
    List<Integer> visited = new ArrayList<>();

    int time = 0;
    queue.add(0);
    while (!queue.isEmpty()) {
        int current = queue.remove();
        visited.add(current);

        if (hasApple[current]) {
            return time;
        }

        for (int neighbor : graph.get(current)) {
            if (!visited.contains(neighbor)) {
                queue.add(neighbor);
            }
        }
    }

    return -1;
}

public String sortString(String s) {
    Deque<Character> stack = new ArrayDeque<>();
    StringBuilder result = new StringBuilder();
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    for (char c : chars) {
        stack.push(c);
        while (!stack.isEmpty() && stack.peekLast() > c) {
            c = stack.pop();
            result.append(c);
        }
    }
    while (!stack.isEmpty()) {
        result.append(stack.pop());
    }
    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    // Step 1: Pick the smallest character from s and append it to the result
    char smallestChar = s.charAt(0);
    String result = "" + smallestChar;

    // Step 2: Pick the smallest character from s which is greater than the last appended character to the result and append it
    for (int i = 1; i < s.length(); i++) {
        char currentChar = s.charAt(i);
        if (currentChar > smallestChar && result.charAt(result.length() - 1) < currentChar) {
            smallestChar = currentChar;
            result += currentChar;
            break;
        }
    }

    // Step 3: Repeat step 2 until you cannot pick more characters
    while (result.length() < s.length()) {
        for (int i = 0; i < s.length(); i++) {
            char currentChar = s.charAt(i);
            if (currentChar > smallestChar && result.charAt(result.length() - 1) < currentChar) {
                smallestChar = currentChar;
                result += currentChar;
                break;
            }
        }
    }

    // Step 4: Pick the largest character from s and append it to the result
    char largestChar = s.charAt(s.length() - 1);
    for (int i = s.length() - 2; i >= 0; i--) {
        char currentChar = s.charAt(i);
        if (currentChar < largestChar && result.charAt(result.length() - 1) > currentChar) {
            largestChar = currentChar;
            result += currentChar;
            break;
        }
    }

    // Step 5: Pick the largest character from s which is smaller than the last appended character to the result and append it
    while (result.length() < s.length()) {
        for (int i = s.length() - 2; i >= 0; i--) {
            char currentChar = s.charAt(i);
            if (currentChar < largestChar && result.charAt(result.length() - 1) < currentChar) {
                largestChar = currentChar;
                result += currentChar;
                break;
            }
        }
    }

    // Step 6: Repeat step 5 until you cannot pick more characters
    while (result.length() < s.length()) {
        for (int i = 0; i < s.length(); i++) {
            char currentChar = s.charAt(i);
            if (currentChar > smallestChar && result.charAt(result.length() - 1) > currentChar) {
                smallestChar = currentChar;
                result += currentChar;
                break;
            }
        }
    }

    // Step 7: Repeat the steps from 1 to 6 until you pick all characters from s
    while (result.length() < s.length()) {
        for (int i = 1; i < s.length(); i++) {
            char currentChar = s.charAt(i);
            if (currentChar > smallestChar && result.charAt(result.length() - 1) > currentChar) {
                smallestChar = currentChar;
                result += currentChar;
                break;
            }
        }
    }

    return result;
}

public String sortString(String s) {
    List<Character> chars = new ArrayList<>(s.length());
    for (char c : s.toCharArray()) {
        chars.add(c);
    }
    chars.sort((c1, c2) -> Character.compare(c1, c2));
    String result = "";
    while (!chars.isEmpty()) {
        char min = chars.remove(0);
        while (chars.remove(chars.size() - 1) != min) {
            if (chars.isEmpty()) {
                break;
            }
        }
        result += min;
        if (!chars.isEmpty()) {
            char max = chars.remove(chars.size() - 1);
            while (chars.remove(0) != max) {
                if (chars.isEmpty()) {
                    break;
                }
            }
            result += max;
        }
    }
    return result;
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();

    // Step 1
    for (int i = 0; i < s.length(); i++) {
        char smallest = s.charAt(i);
        result.append(smallest);

        // Step 2
        for (int j = i + 1; j < s.length(); j++) {
            char nextSmallest = s.charAt(j);
            if (nextSmallest > smallest) {
                result.append(nextSmallest);
                i = j;
                break;
            }
        }
    }

    // Step 3
    for (int i = s.length() - 1; i >= 0; i--) {
        char largest = s.charAt(i);
        result.append(largest);

        // Step 4
        for (int j = i - 1; j >= 0; j--) {
            char nextLargest = s.charAt(j);
            if (nextLargest < largest) {
                result.append(nextLargest);
                i = j;
                break;
            }
        }
    }

    return result.toString();
}

public String sortString(String s) {
    char[] charArray = s.toCharArray();
    Arrays.sort(charArray);
    StringBuilder result = new StringBuilder();
    int len = charArray.length;

    for (int i = 0; i < len; i++) {
        if (i == 0 || charArray[i] > result.charAt(result.length() - 1)) {
            while (i + 1 < len && charArray[i + 1] == charArray[i]) {
                i++;
            }
        } else if (result.length() != 0 && charArray[i] < result.charAt(result.length() - 1)) {
            while (i + 1 < len && charArray[i + 1] == charArray[i]) {
                i++;
            }
        }
        result.append(charArray[i]);
    }

    return result.toString();
}

