    for (int num : nums) {
        sum += num;
    }
    int average = sum / nums.length;

    int leftSum = 0;
    int rightSum = 0;
    for (int i = 0; i < nums.length; i++) {
        if (leftSum == average) {
            rightSum += nums[i];
        } else if (rightSum == average) {
            leftSum += nums[i];
        } else {
            leftSum += nums[i];
            rightSum += average - nums[i];
        }
    }

