    int average = sum / nums.length;

    // Initialize two sets to store the elements of the arrays
    Set<Integer> set1 = new HashSet<>();
    Set<Integer> set2 = new HashSet<>();

    // Iterate over the array elements
    for (int num : nums) {
        // If the element is greater than the average, add it to set 1
        if (num > average) {
            set1.add(num);
        }
        // If the element is less than the average, add it to set 2
