public boolean splitArraySameAverage(int[] nums) {
    // Calculate the sum and average of the input array
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    double average = (double) sum / nums.length;

    // Initialize variables to keep track of the left and right subarrays
    int leftSum = 0;
    int rightSum = sum;
    int leftCount = 0;
    int rightCount = nums.length - 1;

    // Iterate through the input array, alternating between adding numbers to the left subarray and right subarray
    for (int i = 0; i < nums.length; i++) {
        int num = nums[i];
        if (leftSum / leftCount < average) {
            leftSum += num;
            leftCount++;
        } else {
            rightSum -= num;
            rightCount--;
        }
    }

    // Check if the left and right subarrays have the same average
    return leftSum / leftCount == rightSum / rightCount;
}

public int minCostClimbingStairs(int[] cost) {
    // Edge case: empty array
    if (cost.length == 0) {
        return 0;
    }

    // Initialize variables
    int minCost = Integer.MAX_VALUE;
    int bestCostOne = cost[0];
    int bestCostTwo = cost[1];

    // Iterate through the array
    for (int i = 2; i < cost.length; i++) {
        int tempOne = bestCostOne;
        int tempTwo = bestCostTwo;
        bestCostOne = Math.min(tempOne, tempTwo) + cost[i];
        bestCostTwo = bestCostOne;
        if (tempOne < minCost) {
            minCost = tempOne;
        }
        if (tempTwo < minCost) {
            minCost = tempTwo;
        }
    }
    // Return the minimum cost
    return Math.min(minCost, bestCostTwo);
}

