public boolean hasAllCodes(String s, int k) {
  if (s.length() < k) {
    return false;
  }

  char[] chars = s.toCharArray();
  for (int i = 0; i < s.length() - k + 1; i++) {
    StringBuilder sb = new StringBuilder();
    for (int j = 0; j < k; j++) {
      sb.append(chars[i + j]);
    }
    if (!sb.toString().equals(new String(chars, i, k))) {
      return false;
    }
  }
  return true;
}

public boolean hasAllCodes(String s, int k) {
    for (int i = 0; i < Math.pow(2, k); i++) {
        String substr = Integer.toBinaryString(i);
        if (!s.contains(substr)) {
            return false;
        }
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    int len = s.length();
    for (int i = 0; i < len - k + 1; i++) {
        if (!s.substring(i, i + k).matches("[01]{" + k + "}")) {
            return false;
        }
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    for (int i = 0; i < (int) Math.pow(2, k); i++) {
        String binary = Integer.toBinaryString(i);
        if (!s.contains(binary)) {
            return false;
        }
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    int count = 0;
    for (int i = 0; i < s.length() - k + 1; i++) {
        String sub = s.substring(i, i + k);
        if (sub.matches("[^01]{k}")) {
            return false;
        }
        count++;
    }
    return count == (1 << k);
}

