public int minInsertions(String s) {
  // Initialize balance count
  int balance = 0;

  // Traverse the string
  for (char c : s.toCharArray()) {
    // If char is '(', increase balance count
    if (c == '(') {
      balance++;
    }
    // If char is ')', decrease balance count
    else if (c == ')') {
      balance--;
    }
    // If balance count becomes negative, add ')'
    else if (balance < 0) {
      balance++;
    }
  }

  // Return the absolute value of balance count
  return Math.abs(balance);
}

public int minInsertions(String s) {
    int left = 0, right = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            left++;
        } else {
            right++;
        }

        if (left > right) {
            right++;
        } else if (right > left) {
            left++;
        }
    }

    return Math.abs(left - right);
}

public int minInsertions(String s) {
    int open = 0;
    int close = 0;
    int minInsertions = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            open++;
        } else {
            close++;
        }
        if (open > close) {
            minInsertions++;
            open--;
        }
    }
    return minInsertions + Math.abs(open - close);
}

public int minInsertions(String s) {
  // Count the number of left and right brackets using a counter
  int lCount = 0, rCount = 0;
  for (char c : s.toCharArray()) {
    if (c == '(') {
      lCount++;
    } else {
      rCount++;
    }
  }

  // Check if the brackets are balanced
  if (lCount == rCount) {
    return 0;
  }

  // Add the necessary number of parentheses to make the count even
  int insertions = lCount - rCount;
  if (insertions % 2 == 0) {
    return insertions;
  }
  return insertions + 1;
}

public int minInsertions(String s) {
    int left = 0, right = 0, min = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') left++;
        else right++;
        min = Math.min(min, Math.min(left, right));
    }

    return Math.min(min, Math.abs(left - right));
}

