public int minOperations(int n) {
    int minOps = 0;
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    while (arr[0] != arr[n - 1]) {
        int x = 0;
        int y = n - 1;
        while (arr[x] == arr[y]) {
            x++;
            y--;
        }

        arr[x] -= 1;
        arr[y] += 1;
        minOps++;
    }

    return minOps;
}

public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int minOperations = 0;
    while (arr.length > 1) {
        // Find the two smallest elements
        int min1 = Integer.MAX_VALUE;
        int min2 = Integer.MAX_VALUE;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] < min1) {
                min2 = min1;
                min1 = arr[i];
            } else if (arr[i] < min2) {
                min2 = arr[i];
            }
        }

        // Subtract 1 from the smallest element and add 1 to the second-smallest element
        arr[arr.length - 1] = min2 - 1;
        arr[0] = min1 - 1;

        // Remove the two smallest elements
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] == min1) {
                arr[i] = Integer.MAX_VALUE;
            } else if (arr[i] == min2) {
                arr[i] = Integer.MAX_VALUE;
            }
        }

        // Increment the number of operations
        minOperations++;
    }

    return minOperations;
}

public int minOperations(int n) {
  int minOps = 0;
  while (n % 2 == 0) {
    n /= 2;
    minOps++;
  }

  while (n > 1) {
    minOps++;
    n = (n + 1) / 2;
  }

  return minOps;
}

public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int minOps = 0;
    while (arr[0] != arr[n - 1]) {
        int x = 0;
        int y = n - 1;
        while (arr[x] != arr[y]) {
            if (arr[x] < arr[y]) {
                x++;
            } else {
                y--;
            }
        }

        arr[x]--;
        arr[y]++;
        minOps++;
    }

    return minOps;
}

