public int findMinFibonacciNumbers(int k) {
    int[] fibonacci = new int[] {1, 1};

    while (fibonacci[fibonacci.length - 1] < k) {
        int[] newFibonacci = new int[fibonacci.length + 1];
        for (int i = 0; i < fibonacci.length; i++) {
            newFibonacci[i] = fibonacci[i] + fibonacci[i + 1];
        }
        fibonacci = newFibonacci;
    }

    int count = 0;
    for (int i = 0; i < fibonacci.length && k > 0; i++) {
        if (fibonacci[i] <= k) {
            count++;
            k -= fibonacci[i];
        }
    }

    return count;
}

