public int kthFactor(int n, int k) {
  // Initialize the number of factors to 0
  int numFactors = 0;

  // Loop through the numbers from 1 to n
  for (int i = 1; i <= n; i++) {
    // Check if i is a factor of n
    if (n % i == 0) {
      // If it is, increment the number of factors
      numFactors++;

      // If the number of factors is equal to k, return i
      if (numFactors == k) {
        return i;
      }
    }
  }

  // If the number of factors is less than k, return -1
  if (numFactors < k) {
    return -1;
  }
}

