public int kthFactor(int n, int k) {
    // Edge case: If k is 1, the kth factor is n itself.
    if (k == 1) {
      return n;
    }

    // Find all factors of n.
    int[] factors = new int[n / 2 + 1];
    factors[0] = 1;
    for (int i = 2; i <= n / 2; i++) {
      if (n % i == 0) {
        factors[factors.length - 1] = i;
      }
    }

    // Return the kth factor.
    return factors[k - 2];
  }

