public int maxUniqueSplit(String s) {
    // Initialize a hash set to store all unique substrings
    Set<String> uniqueSubstrings = new HashSet<>();

    // Add the first character to the hash set
    uniqueSubstrings.add(s.substring(0, 1));

    // Iterate over each character in the string
    for (int i = 1; i < s.length(); i++) {
        // If the current character is already in the hash set, remove it
        if (uniqueSubstrings.contains(s.substring(i, i + 1))) {
            uniqueSubstrings.remove(s.substring(i, i + 1));
        }
        // Otherwise, add the current character to the hash set
        else {
            uniqueSubstrings.add(s.substring(i, i + 1));
        }
    }

    // Return the size of the hash set
    return uniqueSubstrings.size();
}

