public int maxUniqueSplit(String s) {
        // Count the number of unique letters in each substring
        int[] letterCount = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            char letter = s.charAt(i);
            for (int j = i + 1; j < s.length(); j++) {
                if (s.charAt(j) == letter) {
                    letterCount[i]++;
                    break;
                }
            }
        }

        // Find the maximum number of unique substrings
        int maxUnique = 0;
        for (int i = 0; i < s.length(); i++) {
            if (letterCount[i] == 0) {
                continue;
            }
            maxUnique++;
            for (int j = i + 1; j < s.length(); j++) {
                if (letterCount[j] == 0) {
                    continue;
                }
                maxUnique++;
                int k = j + 1;
                while (k < s.length() && letterCount[k] == 0) {
                    k++;
                }
                if (k == s.length()) {
                    break;
                }
                letterCount[k]++;
            }
        }
        return maxUnique;
    }

private int maxUniqueSplit(String s) {
    Set<String> uniqueStrings = new HashSet<>();
    uniqueStrings.add(s);
    int maxCount = 1;
    while (s.matches(".*[a-z].*")) {
        int end = s.indexOf("[a-z]", s.lastIndexOf("[a-z]")) + 1;
        end = Math.min(end, s.length());
        for (int i = s.indexOf("[a-z]"); i < s.length(); i++) {
            if (i - end >= 3) {
                break;
            }
            String substring = s.substring(i, end);
            if (uniqueStrings.contains(substring)) {
                continue;
            }
            uniqueStrings.add(substring);
            if (uniqueStrings.size() > maxCount) {
                maxCount++;
            }
        }
    }
    return maxCount;
}

