public static double calculateProbability(int n) {
        // Base case: If there is only one person, the probability is 1.
        if (n == 1) {
            return 1.0;
        }

        // Recursive case: Calculate the probability for n - 1 passengers.
        double probability = 1.0 - calculateProbability(n - 1);

        // Calculate the probability of the last passenger sitting in their own seat.
        if (n % 2 == 0) {
            // If there are an even number of passengers, the last passenger has a 50% chance of sitting in their own seat.
            probability /= 2;
        } else {
            // If there are an odd number of passengers, the last passenger has a 50% chance of sitting in their own seat, and a 50% chance of sitting in the next seat over.
            probability /= 4;
        }

        return probability;
    }

