      double numFavorableOutcomes = 1.0;
      double totalOutcomes = 1.0;
      for (int i = 1; i <= n; i++) {
          numFavorableOutcomes *= (i - 1) / i;
          totalOutcomes *= i;
      }
      return numFavorableOutcomes / totalOutcomes;
  }

