    // Initialize variables
    int maxArea = 0;
    int currentHeight = heights[0];
    int currentWidth = 1;

    // Iterate through the heights array
    for (int i = 1; i < heights.length; i++) {
        // If the current height is less than the previous height,
        // Update the current width and current height
        if (heights[i] < currentHeight) {
            maxArea = Math.max(maxArea, currentHeight * currentWidth);
            currentWidth = i - currentWidth + 1;
            currentHeight = heights[i];
        // Otherwise, update the current height
        } else {
            currentHeight = Math.max(heights[i], currentHeight);
        }
    }

    // Calculate the final area
    maxArea = Math.max(maxArea, currentHeight * currentWidth);

    return maxArea;
}

