    int diag = n - 1;
    for (int i = 0; i < n; i++) {
        diag += Math.min(i, n - 1 - i);
    }

    // Step 2: Resize the output array
    int[] res = new int[diag];

    // Step 3: Fill in the output array
    int r = 0, c = 0;
    while (r < n && c < n) {
        res[r++] = mat[c][c++];
