    while (r < diag) {
        if (c == n) {
            c = n - 1;
            r++;
        } else if (r == n) {
            r = n - 1;
            c++;
        } else if (c > r) {
            res[r++] = mat[c][c--];
        } else {
            res[r++] = mat[r][c++];
        }
    }
    return res;
}

