  int sideBLength = Math.abs(points[2][0] - points[1][0]);
  int sideCLength = Math.abs(points[0][0] - points[2][0]);

  int sideADoubleLength = 2 * sideALength;
  int sideBDoubleLength = 2 * sideBLength;
  int sideCDoubleLength = 2 * sideCLength;

  int perimeter = sideADoubleLength + sideBDoubleLength + sideCDoubleLength;

  // Using the Shoelace formula
  int area = points[0][0] * points[1][1] + points[1][0] * points[2][1] + points[2][0] * points[0][1] - points[0][0] * points[2][1] - points[1][0] * points[0][1] - points[2][0] * points[1][1];

