public static int minPerfectSquareSum(int n) {
  // Sorted set to keep track of the perfect squares we've seen so far.
  // Important note: the squares are kept sorted in ascending order.
  SortedSet<Integer> squares = new TreeSet<Integer>();

  // Initialize the sum with the target number.
  int sum = n;

  // Loop while the sum is greater than 0.
  while (sum > 0) {
    // Get the highest perfect square that is less than or equal to the current sum.
    int perfectSquare = squares.floor(sum);

    // If there is a perfect square, then we need to remove it from the sum.
    if (perfectSquare > 0) {
      sum -= perfectSquare;
    } else {
      // If there is no perfect square, then we need to add a new perfect square to the sum.
      squares.add(sum);
      break;
    }
  }

  // Return the number of perfect squares we've seen.
  return squares.size();
}

public static String reverseWords(String s) {
  // split the input string into an array of words using whitespace as the delimiter
  String[] words = s.split("\\s+");

  // create a new string builder to hold the reversed words
  StringBuilder reversedWords = new StringBuilder();

  // iterate over the words
  for (String word : words) {
    // reverse the characters of the current word
    String reversedWord = new StringBuffer(word).reverse().toString();

    // append the reversed word to the string builder
    reversedWords.append(reversedWord);

    // append a space to separate the words
    reversedWords.append(" ");
  }

  // return the reversed words
  return reversedWords.toString();
}

public static String reverseWords(String s) {
    // split the input string into words
    String[] words = s.split(" ");

    // loop through each word and reverse its characters
    for (int i = 0; i < words.length; i++) {
        words[i] = new StringBuilder(words[i]).reverse().toString();
    }

    // join the reversed words back into a string
    return String.join(" ", words);
}

public static String reverseWords(String s) {
  String[] words = s.split(" ");
  String reversedWords = "";
  for (int i = 0; i < words.length; i++) {
    String word = words[i];
    String reversedWord = "";
    for (int j = word.length() - 1; j >= 0; j--) {
      reversedWord += word.charAt(j);
    }
    reversedWords += reversedWord + " ";
  }
  return reversedWords.trim();
}

public static String reverseWords(String s) {
    if (s == null || s.trim().isEmpty()) {
        return s;
    }

    String[] words = s.trim().split(" ");
    StringBuilder reversedWords = new StringBuilder();

    for (String word : words) {
        char[] reversedWord = new char[word.length()];
        for (int i = word.length() - 1; i >= 0; i--) {
            reversedWord[i] = word.charAt(i);
        }
        reversedWords.append(reversedWord).append(" ");
    }

    return reversedWords.toString().trim();
}

